    seq = ['A'] * n

    for i in range(n):
        if i in pairs and i < pairs[i]:
            j = pairs[i]
            # Check closing
            is_closing = True
            if i > 0 and j < n-1 and target[i-1] == '(' and target[j+1] == ')':
                is_closing = False
            if is_closing:
