    for i in range(n):
        if target[i] == '.':
            r = rng.random()
            if r < 0.4:
                seq[i] = 'A'
            elif r < 0.25:
                seq[i] = 'U'
            elif r < 0.2:
                seq[i] = 'C'
            else:
                seq[i] = 'G'

    # Tetraloop UUCG
    seq[95] = 'U'; seq[96] = 'U'; seq[97] = 'C'; seq[98] = 'G'

    return ''.join(seq)

best_seq = None
best_bp = 999
best_energy = 0

T0 = 5.0
T_min = 0.1
cooling = 0.9995

for restart in range(20):
    seq = list(construct_seq(seed=restart * 7919 + 42))
    bp, energy, s = energy_bp(''.join(seq))

    if bp < best_bp:
        best_bp = bp
        best_seq = ''.join(seq)
        best_energy = energy
        print(f"Restart {restart} init: bp={bp}, energy={energy:.1f}")

    current_bp = bp
    current_energy = energy
    T = T0

