def build_block(outer, stem1, stem2, stem3, loops):
    seq = []
    # outer 5' (reversed)
    for p in reversed(outer):
        seq.append(p[0])
    # stem1 5' (reversed: first pair is innermost/closing)
    for p in reversed(stem1):
